import os
import math
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Ensure we compile with hipcc on ROCm
os.environ.setdefault("CXX", "hipcc")

# HIP/C++ extension: fused RoPE + causal GQA attention (no KV expansion, no materialized attn weights)
# Notes:
# - Optimized for FP32, head_dim==128, wavefront=64.
# - Computes output in layout [B, L, H*D] to feed o_proj directly.

_gqa_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <hip/hip_runtime.h>
#include <vector>
#include <cmath>

// HIP shuffle helpers
__device__ __forceinline__ float shfl_down_f32(float v, int offset, int width=64) {
#if defined(__HIP_PLATFORM_AMD__)
    return __shfl_down(v, offset, width);
#else
    return __shfl_down(v, offset, width);
#endif
}

__device__ __forceinline__ float shfl_f32(float v, int src_lane, int width=64) {
#if defined(__HIP_PLATFORM_AMD__)
    return __shfl(v, src_lane, width);
#else
    return __shfl(v, src_lane, width);
#endif
}

// q: [B, H, L, D] (strided from transpose)
// k: [B, KVH, L, D]
// v: [B, KVH, L, D]
// cos/sin: [1, 1, L, D]
// out: [B, L, H*D]
__global__ void gqa_flash_attn_rope_fwd_f32_hd128(
    const float* __restrict__ q,
    const float* __restrict__ k,
    const float* __restrict__ v,
    const float* __restrict__ cos,
    const float* __restrict__ sin,
    float* __restrict__ out,
    int B, int H, int KVH, int L,
    float scale,
    int groups,
    int64_t qs0, int64_t qs1, int64_t qs2,
    int64_t ks0, int64_t ks1, int64_t ks2,
    int64_t vs0, int64_t vs1, int64_t vs2,
    int64_t cs2, int64_t cs3,
    int64_t ss2, int64_t ss3,
    int64_t os0, int64_t os1
) {
    // grid: (L, H, B)
    const int i = (int)blockIdx.x; // query position
    const int h = (int)blockIdx.y; // query head
    const int b = (int)blockIdx.z; // batch

    const int lane = (int)threadIdx.x; // 0..63

    // head_dim fixed
    const int d0 = lane;
    const int d1 = lane + 64;

    const int kv_h = h / groups;

    // Load q vector for this (b,h,i)
    const float* q_ptr = q + b*qs0 + h*qs1 + i*qs2;
    float q0 = q_ptr[d0];
    float q1 = q_ptr[d1];

    // RoPE for query at position i
    const float c0q = cos[i*cs2 + d0*cs3];
    const float s0q = sin[i*ss2 + d0*ss3];
    const float c1q = cos[i*cs2 + d1*cs3];
    const float s1q = sin[i*ss2 + d1*ss3];

    // rotate_half: first half uses -second_half, second half uses first_half
    const float q0_rot = -q1;
    const float q1_rot =  q0;

    const float q0e = q0 * c0q + q0_rot * s0q;
    const float q1e = q1 * c1q + q1_rot * s1q;

    // Online softmax accumulators (only lane0 needs m,l; all lanes keep acc vector)
    float acc0 = 0.0f;
    float acc1 = 0.0f;

    float m = -INFINITY;
    float lsum = 0.0f;

    // Base pointers for K/V head
    const float* k_head = k + b*ks0 + kv_h*ks1;
    const float* v_head = v + b*vs0 + kv_h*vs1;

    // Loop over keys 0..i (causal)
    for (int j = 0; j <= i; ++j) {
        const float* k_ptr = k_head + j*ks2;
        const float* v_ptr = v_head + j*vs2;

        float k0 = k_ptr[d0];
        float k1 = k_ptr[d1];

        // RoPE for key at position j
        const float c0k = cos[j*cs2 + d0*cs3];
        const float s0k = sin[j*ss2 + d0*ss3];
        const float c1k = cos[j*cs2 + d1*cs3];
        const float s1k = sin[j*ss2 + d1*ss3];

        const float k0_rot = -k1;
        const float k1_rot =  k0;

        const float k0e = k0 * c0k + k0_rot * s0k;
        const float k1e = k1 * c1k + k1_rot * s1k;

        // dot(q, k)
        float partial = q0e * k0e + q1e * k1e;
        // reduce within wavefront (64)
        for (int off = 32; off > 0; off >>= 1) {
            partial += shfl_down_f32(partial, off, 64);
        }
        const float dot = shfl_f32(partial, 0, 64);
        const float s = dot * scale;

        // lane0 updates m, lsum and produces alpha/beta
        float alpha = 0.0f;
        float beta  = 0.0f;
        if (lane == 0) {
            const float m_new = fmaxf(m, s);
            // rescale previous sum
            alpha = expf(m - m_new);
            beta  = expf(s - m_new);
            lsum  = lsum * alpha + beta;
            m = m_new;
        }
        alpha = shfl_f32(alpha, 0, 64);
        beta  = shfl_f32(beta,  0, 64);

        // accumulate weighted V
        const float v0 = v_ptr[d0];
        const float v1 = v_ptr[d1];
        acc0 = acc0 * alpha + beta * v0;
        acc1 = acc1 * alpha + beta * v1;
    }

    // normalize
    float denom = lsum;
    denom = shfl_f32(denom, 0, 64);
    acc0 = acc0 / denom;
    acc1 = acc1 / denom;

    // write to out [B, L, H*D]
    float* out_ptr = out + b*os0 + i*os1 + h*128;
    out_ptr[d0] = acc0;
    out_ptr[d1] = acc1;
}

torch::Tensor gqa_flash_attn_rope_fwd(torch::Tensor q, torch::Tensor k, torch::Tensor v, torch::Tensor cos, torch::Tensor sin, double scale, int64_t groups) {
    TORCH_CHECK(q.is_cuda(), "q must be CUDA/HIP tensor");
    TORCH_CHECK(k.is_cuda() && v.is_cuda(), "k/v must be CUDA/HIP tensors");
    TORCH_CHECK(cos.is_cuda() && sin.is_cuda(), "cos/sin must be CUDA/HIP tensors");
    TORCH_CHECK(q.scalar_type() == at::kFloat, "FP32 only");
    TORCH_CHECK(k.scalar_type() == at::kFloat && v.scalar_type() == at::kFloat, "FP32 only");
    TORCH_CHECK(cos.scalar_type() == at::kFloat && sin.scalar_type() == at::kFloat, "FP32 only");
    TORCH_CHECK(q.dim() == 4 && k.dim() == 4 && v.dim() == 4, "q/k/v must be 4D");
    TORCH_CHECK(q.size(3) == 128, "This optimized kernel currently supports head_dim==128");

    const int B = (int)q.size(0);
    const int H = (int)q.size(1);
    const int L = (int)q.size(2);
    const int D = (int)q.size(3);
    const int KVH = (int)k.size(1);

    TORCH_CHECK(k.size(0) == B && v.size(0) == B, "batch mismatch");
    TORCH_CHECK(k.size(2) == L && v.size(2) == L, "seq mismatch");
    TORCH_CHECK(k.size(3) == D && v.size(3) == D, "head_dim mismatch");

    auto out = torch::empty({B, L, H * D}, q.options());

    const int64_t qs0 = q.stride(0);
    const int64_t qs1 = q.stride(1);
    const int64_t qs2 = q.stride(2);

    const int64_t ks0 = k.stride(0);
    const int64_t ks1 = k.stride(1);
    const int64_t ks2 = k.stride(2);

    const int64_t vs0 = v.stride(0);
    const int64_t vs1 = v.stride(1);
    const int64_t vs2 = v.stride(2);

    // cos/sin: [1,1,L,D]
    TORCH_CHECK(cos.dim() == 4 && sin.dim() == 4, "cos/sin must be 4D");
    TORCH_CHECK(cos.size(2) >= L && cos.size(3) == D, "cos shape mismatch");
    TORCH_CHECK(sin.size(2) >= L && sin.size(3) == D, "sin shape mismatch");

    const int64_t cs2 = cos.stride(2);
    const int64_t cs3 = cos.stride(3);
    const int64_t ss2 = sin.stride(2);
    const int64_t ss3 = sin.stride(3);

    const int64_t os0 = out.stride(0);
    const int64_t os1 = out.stride(1);

    const dim3 grid(L, H, B);
    const dim3 block(64);

    hipStream_t stream = (hipStream_t)at::cuda::getDefaultCUDAStream();

    hipLaunchKernelGGL(
        gqa_flash_attn_rope_fwd_f32_hd128,
        grid,
        block,
        0,
        stream,
        (const float*)q.data_ptr<float>(),
        (const float*)k.data_ptr<float>(),
        (const float*)v.data_ptr<float>(),
        (const float*)cos.data_ptr<float>(),
        (const float*)sin.data_ptr<float>(),
        (float*)out.data_ptr<float>(),
        B, H, KVH, L,
        (float)scale,
        (int)groups,
        qs0, qs1, qs2,
        ks0, ks1, ks2,
        vs0, vs1, vs2,
        cs2, cs3,
        ss2, ss3,
        os0, os1
    );

    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("gqa_flash_attn_rope_fwd", &gqa_flash_attn_rope_fwd, "GQA FlashAttn RoPE fwd (FP32, hd=128)");
}
"""

# Build extension lazily (import-time JIT is fine for KernelBench)
_gqa_ext = load_inline(
    name="gqa_flash_attn_rope_ext",
    cpp_sources="",
    cuda_sources=_gqa_src,
    functions=None,
    extra_cuda_cflags=["-O3", "-ffast-math"],
    with_cuda=True,
    verbose=False,
)


def rotate_half(x):
    x1 = x[..., : x.shape[-1] // 2]
    x2 = x[..., x.shape[-1] // 2 :]
    return torch.cat((-x2, x1), dim=-1)


class RotaryEmbedding(nn.Module):
    def __init__(self, dim, max_position_embeddings=4096, base=10000.0):
        super().__init__()
        self.dim = dim
        self.max_position_embeddings = max_position_embeddings
        self.base = base
        inv_freq = 1.0 / (self.base ** (torch.arange(0, self.dim, 2, dtype=torch.float32) / self.dim))
        self.register_buffer("inv_freq", inv_freq, persistent=False)

    @torch.no_grad()
    def forward(self, x, seq_len=None):
        if seq_len is None:
            seq_len = x.shape[-2]
        t = torch.arange(seq_len, device=x.device, dtype=torch.float32)
        freqs = torch.outer(t, self.inv_freq)
        emb = torch.cat((freqs, freqs), dim=-1)
        return emb.cos().unsqueeze(0).unsqueeze(0), emb.sin().unsqueeze(0).unsqueeze(0)


class ModelNew(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        num_attention_heads: int,
        num_key_value_heads: int,
        head_dim: int,
        max_position_embeddings: int = 4096,
        rope_theta: float = 10000.0,
        attention_dropout: float = 0.0,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.num_heads = num_attention_heads
        self.num_kv_heads = num_key_value_heads
        self.head_dim = head_dim
        self.num_key_value_groups = num_attention_heads // num_key_value_heads
        self.attention_dropout = attention_dropout
        self.softmax_scale = head_dim ** (-0.5)

        self.q_proj = nn.Linear(hidden_size, num_attention_heads * head_dim, bias=False)
        self.k_proj = nn.Linear(hidden_size, num_key_value_heads * head_dim, bias=False)
        self.v_proj = nn.Linear(hidden_size, num_key_value_heads * head_dim, bias=False)
        self.o_proj = nn.Linear(num_attention_heads * head_dim, hidden_size, bias=False)

        self.rotary_emb = RotaryEmbedding(
            head_dim,
            max_position_embeddings=max_position_embeddings,
            base=rope_theta,
        )

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        # FP32 kernel: keep computations in FP32
        hidden_states = hidden_states.to(dtype=torch.float32)
        bsz, q_len, _ = hidden_states.size()

        # Projections (left to PyTorch/rocBLAS)
        q = self.q_proj(hidden_states)
        k = self.k_proj(hidden_states)
        v = self.v_proj(hidden_states)

        # Reshape to [B, H, L, D] and [B, KVH, L, D] (strided, no copies)
        q = q.view(bsz, q_len, self.num_heads, self.head_dim).transpose(1, 2)
        k = k.view(bsz, q_len, self.num_kv_heads, self.head_dim).transpose(1, 2)
        v = v.view(bsz, q_len, self.num_kv_heads, self.head_dim).transpose(1, 2)

        # Rotary embedding tables
        cos, sin = self.rotary_emb(v, seq_len=q_len)

        # Fused attention: produces [B, L, H*D]
        if self.head_dim != 128 or q.dtype != torch.float32:
            # Conservative fallback (shouldn't trigger for the provided benchmark)
            # Apply RoPE using PyTorch and run baseline attention without explicit KV repeat.
            # (Still avoids materializing attention weights if possible.)
            q_embed = (q * cos) + (rotate_half(q) * sin)
            k_embed = (k * cos) + (rotate_half(k) * sin)
            # Implicit KV repeat using indexing
            # [B, H, L, D]
            kv_h = torch.arange(self.num_heads, device=q.device) // self.num_key_value_groups
            k_rep = k_embed[:, kv_h]
            v_rep = v[:, kv_h]
            attn = torch.matmul(q_embed, k_rep.transpose(2, 3)) * self.softmax_scale
            causal = torch.triu(torch.ones(q_len, q_len, device=q.device, dtype=torch.bool), diagonal=1)
            attn = attn.masked_fill(causal, float('-inf'))
            attn = F.softmax(attn, dim=-1, dtype=torch.float32)
            out = torch.matmul(attn, v_rep)
            out = out.transpose(1, 2).contiguous().view(bsz, q_len, self.num_heads * self.head_dim)
        else:
            out = _gqa_ext.gqa_flash_attn_rope_fwd(q, k, v, cos, sin, float(self.softmax_scale), int(self.num_key_value_groups))

        # Output projection
        out = self.o_proj(out)
        return out


# Configuration from the prompt
batch_size = 4
seq_len = 2048
hidden_size = 4096
num_attention_heads = 32
num_key_value_heads = 8
head_dim = 128
max_position_embeddings = 4096


def get_inputs():
    return [torch.randn(batch_size, seq_len, hidden_size, device='cuda', dtype=torch.float32)]


def get_init_inputs():
    return [hidden_size, num_attention_heads, num_key_value_heads, head_dim, max_position_embeddings]

import os
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Compile with hipcc on ROCm
os.environ.setdefault("CXX", "hipcc")

# Fused RoPE + causal grouped-query attention (no KV expansion, no materialized attn matrix)
# Optimized for FP32, head_dim==128, AMD wavefront=64.

_gqa_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <hip/hip_runtime.h>
#include <cmath>

__device__ __forceinline__ float shfl_down_f32(float v, int offset, int width=64) {
    return __shfl_down(v, offset, width);
}

__device__ __forceinline__ float shfl_f32(float v, int src_lane, int width=64) {
    return __shfl(v, src_lane, width);
}

// q: [B, H, L, D] (typically strided due to transpose)
// k/v: [B, KVH, L, D]
// cos/sin: [1, 1, L, D]
// out: [B, L, H*D]
__global__ void gqa_flash_attn_rope_fwd_f32_hd128(
    const float* __restrict__ q,
    const float* __restrict__ k,
    const float* __restrict__ v,
    const float* __restrict__ cos,
    const float* __restrict__ sin,
    float* __restrict__ out,
    int B, int H, int KVH, int L,
    float scale,
    int groups,
    int64_t qs0, int64_t qs1, int64_t qs2,
    int64_t ks0, int64_t ks1, int64_t ks2,
    int64_t vs0, int64_t vs1, int64_t vs2,
    int64_t cs2, int64_t cs3,
    int64_t ss2, int64_t ss3,
    int64_t os0, int64_t os1
) {
    const int i = (int)blockIdx.x; // query position
    const int h = (int)blockIdx.y; // query head
    const int b = (int)blockIdx.z; // batch

    const int lane = (int)threadIdx.x; // 0..63
    const int d0 = lane;
    const int d1 = lane + 64;

    const int kv_h = h / groups;

    // q(b,h,i,:)
    const float* q_ptr = q + b*qs0 + h*qs1 + i*qs2;
    float q0 = q_ptr[d0];
    float q1 = q_ptr[d1];

    // RoPE for q at position i
    const float c0q = cos[i*cs2 + d0*cs3];
    const float s0q = sin[i*ss2 + d0*ss3];
    const float c1q = cos[i*cs2 + d1*cs3];
    const float s1q = sin[i*ss2 + d1*ss3];

    const float q0_rot = -q1;
    const float q1_rot =  q0;

    const float q0e = q0 * c0q + q0_rot * s0q;
    const float q1e = q1 * c1q + q1_rot * s1q;

    float acc0 = 0.0f;
    float acc1 = 0.0f;

    float m = -INFINITY;
    float lsum = 0.0f;

    const float* k_head = k + b*ks0 + kv_h*ks1;
    const float* v_head = v + b*vs0 + kv_h*vs1;

    // Causal: keys j<=i
    for (int j = 0; j <= i; ++j) {
        const float* k_ptr = k_head + j*ks2;
        const float* v_ptr = v_head + j*vs2;

        float k0 = k_ptr[d0];
        float k1 = k_ptr[d1];

        // RoPE for k at position j
        const float c0k = cos[j*cs2 + d0*cs3];
        const float s0k = sin[j*ss2 + d0*ss3];
        const float c1k = cos[j*cs2 + d1*cs3];
        const float s1k = sin[j*ss2 + d1*ss3];

        const float k0_rot = -k1;
        const float k1_rot =  k0;

        const float k0e = k0 * c0k + k0_rot * s0k;
        const float k1e = k1 * c1k + k1_rot * s1k;

        // dot(q,k)
        float partial = q0e * k0e + q1e * k1e;
        for (int off = 32; off > 0; off >>= 1) {
            partial += shfl_down_f32(partial, off, 64);
        }
        const float dot = shfl_f32(partial, 0, 64);
        const float s = dot * scale;

        float alpha = 0.0f;
        float beta  = 0.0f;
        if (lane == 0) {
            const float m_new = fmaxf(m, s);
            alpha = expf(m - m_new);
            beta  = expf(s - m_new);
            lsum  = lsum * alpha + beta;
            m = m_new;
        }
        alpha = shfl_f32(alpha, 0, 64);
        beta  = shfl_f32(beta,  0, 64);

        const float v0 = v_ptr[d0];
        const float v1 = v_ptr[d1];
        acc0 = acc0 * alpha + beta * v0;
        acc1 = acc1 * alpha + beta * v1;
    }

    float denom = shfl_f32(lsum, 0, 64);
    acc0 = acc0 / denom;
    acc1 = acc1 / denom;

    float* out_ptr = out + b*os0 + i*os1 + h*128;
    out_ptr[d0] = acc0;
    out_ptr[d1] = acc1;
}

torch::Tensor gqa_flash_attn_rope_fwd(torch::Tensor q, torch::Tensor k, torch::Tensor v, torch::Tensor cos, torch::Tensor sin, double scale, int64_t groups) {
    TORCH_CHECK(q.is_cuda(), "q must be CUDA/HIP");
    TORCH_CHECK(k.is_cuda() && v.is_cuda(), "k/v must be CUDA/HIP");
    TORCH_CHECK(cos.is_cuda() && sin.is_cuda(), "cos/sin must be CUDA/HIP");
    TORCH_CHECK(q.scalar_type() == at::kFloat, "FP32 only");
    TORCH_CHECK(k.scalar_type() == at::kFloat && v.scalar_type() == at::kFloat, "FP32 only");
    TORCH_CHECK(cos.scalar_type() == at::kFloat && sin.scalar_type() == at::kFloat, "FP32 only");
    TORCH_CHECK(q.dim() == 4 && k.dim() == 4 && v.dim() == 4, "q/k/v must be 4D");

    const int B = (int)q.size(0);
    const int H = (int)q.size(1);
    const int L = (int)q.size(2);
    const int D = (int)q.size(3);
    TORCH_CHECK(D == 128, "optimized kernel supports head_dim==128");

    const int KVH = (int)k.size(1);
    TORCH_CHECK(k.size(0) == B && v.size(0) == B, "batch mismatch");
    TORCH_CHECK(k.size(2) == L && v.size(2) == L, "seq mismatch");
    TORCH_CHECK(k.size(3) == D && v.size(3) == D, "head_dim mismatch");

    TORCH_CHECK(cos.dim() == 4 && sin.dim() == 4, "cos/sin must be [1,1,L,D]");
    TORCH_CHECK(cos.size(2) >= L && cos.size(3) == D, "cos shape mismatch");
    TORCH_CHECK(sin.size(2) >= L && sin.size(3) == D, "sin shape mismatch");

    auto out = torch::empty({B, L, H * D}, q.options());

    const int64_t qs0 = q.stride(0);
    const int64_t qs1 = q.stride(1);
    const int64_t qs2 = q.stride(2);

    const int64_t ks0 = k.stride(0);
    const int64_t ks1 = k.stride(1);
    const int64_t ks2 = k.stride(2);

    const int64_t vs0 = v.stride(0);
    const int64_t vs1 = v.stride(1);
    const int64_t vs2 = v.stride(2);

    const int64_t cs2 = cos.stride(2);
    const int64_t cs3 = cos.stride(3);
    const int64_t ss2 = sin.stride(2);
    const int64_t ss3 = sin.stride(3);

    const int64_t os0 = out.stride(0);
    const int64_t os1 = out.stride(1);

    dim3 grid(L, H, B);
    dim3 block(64);

    hipStream_t stream = (hipStream_t)at::cuda::getDefaultCUDAStream();

    hipLaunchKernelGGL(
        gqa_flash_attn_rope_fwd_f32_hd128,
        grid,
        block,
        0,
        stream,
        (const float*)q.data_ptr<float>(),
        (const float*)k.data_ptr<float>(),
        (const float*)v.data_ptr<float>(),
        (const float*)cos.data_ptr<float>(),
        (const float*)sin.data_ptr<float>(),
        (float*)out.data_ptr<float>(),
        B, H, KVH, L,
        (float)scale,
        (int)groups,
        qs0, qs1, qs2,
        ks0, ks1, ks2,
        vs0, vs1, vs2,
        cs2, cs3,
        ss2, ss3,
        os0, os1
    );

    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("gqa_flash_attn_rope_fwd", &gqa_flash_attn_rope_fwd, "GQA fused attention+RoPE forward (FP32, hd=128)");
}
"""

_gqa_ext = load_inline(
