    const int half = D >> 1;
    const int total = B * H * L * half;
    if (idx >= total) return;

    int t = idx;
    const int d = t % half; t /= half;
    const int l = t % L;    t /= L;
    const int h = t % H;    t /= H;
    const int b = t;

