    const float s0 = sin[l*ss2 + d0*ss3];
    const float c1 = cos[l*cs2 + d1*cs3];
    const float s1 = sin[l*ss2 + d1*ss3];

    const float x0_rot = -x1;
    const float x1_rot =  x0;

    base[d0] = x0 * c0 + x0_rot * s0;
    base[d1] = x1 * c1 + x1_rot * s1;
