import os
import math
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Ensure we compile with hipcc on ROCm
os.environ.setdefault("CXX", "hipcc")

# HIP/C++ extension: fused RoPE + causal GQA attention (no KV expansion, no materialized attn weights)
# Notes:
# - Optimized for FP32, head_dim==128, wavefront=64.
# - Computes output in layout [B, L, H*D] to feed o_proj directly.

_gqa_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <hip/hip_runtime.h>
#include <vector>
#include <cmath>

// HIP shuffle helpers
__device__ __forceinline__ float shfl_down_f32(float v, int offset, int width=64) {
#if defined(__HIP_PLATFORM_AMD__)
    return __shfl_down(v, offset, width);
#else
    return __shfl_down(v, offset, width);
#endif
}

__device__ __forceinline__ float shfl_f32(float v, int src_lane, int width=64) {
#if defined(__HIP_PLATFORM_AMD__)
    return __shfl(v, src_lane, width);
#else
    return __shfl(v, src_lane, width);
#endif
}

// q: [B, H, L, D] (strided from transpose)
// k: [B, KVH, L, D]
// v: [B, KVH, L, D]
// cos/sin: [1, 1, L, D]
// out: [B, L, H*D]
__global__ void gqa_flash_attn_rope_fwd_f32_hd128(
    const float* __restrict__ q,
    const float* __restrict__ k,
    const float* __restrict__ v,
    const float* __restrict__ cos,
    const float* __restrict__ sin,
    float* __restrict__ out,
    int B, int H, int KVH, int L,
    float scale,
    int groups,
    int64_t qs0, int64_t qs1, int64_t qs2,
    int64_t ks0, int64_t ks1, int64_t ks2,
    int64_t vs0, int64_t vs1, int64_t vs2,
    int64_t cs2, int64_t cs3,
    int64_t ss2, int64_t ss3,
    int64_t os0, int64_t os1
) {
    // grid: (L, H, B)
    const int i = (int)blockIdx.x; // query position
    const int h = (int)blockIdx.y; // query head
    const int b = (int)blockIdx.z; // batch

    const int lane = (int)threadIdx.x; // 0..63

    // head_dim fixed
    const int d0 = lane;
    const int d1 = lane + 64;

    const int kv_h = h / groups;

    // Load q vector for this (b,h,i)
    const float* q_ptr = q + b*qs0 + h*qs1 + i*qs2;
    float q0 = q_ptr[d0];
    float q1 = q_ptr[d1];

    // RoPE for query at position i
    const float c0q = cos[i*cs2 + d0*cs3];
    const float s0q = sin[i*ss2 + d0*ss3];
    const float c1q = cos[i*cs2 + d1*cs3];
    const float s1q = sin[i*ss2 + d1*ss3];

    // rotate_half: first half uses -second_half, second half uses first_half
    const float q0_rot = -q1;
    const float q1_rot =  q0;

    const float q0e = q0 * c0q + q0_rot * s0q;
    const float q1e = q1 * c1q + q1_rot * s1q;

    // Online softmax accumulators (only lane0 needs m,l; all lanes keep acc vector)
    float acc0 = 0.0f;
    float acc1 = 0.0f;

    float m = -INFINITY;
    float lsum = 0.0f;

    // Base pointers for K/V head
    const float* k_head = k + b*ks0 + kv_h*ks1;
    const float* v_head = v + b*vs0 + kv_h*vs1;

    // Loop over keys 0..i (causal)
    for (int j = 0; j <= i; ++j) {
        const float* k_ptr = k_head + j*ks2;
        const float* v_ptr = v_head + j*vs2;

        float k0 = k_ptr[d0];
        float k1 = k_ptr[d1];

        // RoPE for key at position j
        const float c0k = cos[j*cs2 + d0*cs3];
        const float s0k = sin[j*ss2 + d0*ss3];
        const float c1k = cos[j*cs2 + d1*cs3];
        const float s1k = sin[j*ss2 + d1*ss3];

        const float k0_rot = -k1;
        const float k1_rot =  k0;

        const float k0e = k0 * c0k + k0_rot * s0k;
        const float k1e = k1 * c1k + k1_rot * s1k;

        // dot(q, k)
        float partial = q0e * k0e + q1e * k1e;
        // reduce within wavefront (64)
        for (int off = 32; off > 0; off >>= 1) {
            partial += shfl_down_f32(partial, off, 64);
        }
        const float dot = shfl_f32(partial, 0, 64);
        const float s = dot * scale;

        // lane0 updates m, lsum and produces alpha/beta
        float alpha = 0.0f;
        float beta  = 0.0f;
        if (lane == 0) {
            const float m_new = fmaxf(m, s);
            // rescale previous sum
            alpha = expf(m - m_new);
            beta  = expf(s - m_new);
            lsum  = lsum * alpha + beta;
            m = m_new;
        }
        alpha = shfl_f32(alpha, 0, 64);
        beta  = shfl_f32(beta,  0, 64);

        // accumulate weighted V
        const float v0 = v_ptr[d0];
        const float v1 = v_ptr[d1];
        acc0 = acc0 * alpha + beta * v0;
        acc1 = acc1 * alpha + beta * v1;
    }

    // normalize
    float denom = lsum;
    denom = shfl_f32(denom, 0, 64);
    acc0 = acc0 / denom;
    acc1 = acc1 / denom;

    // write to out [B, L, H*D]
    float* out_ptr = out + b*os0 + i*os1 + h*128;
    out_ptr[d0] = acc0;
    out_ptr[d1] = acc1;
}

torch::Tensor gqa_flash_attn_rope_fwd(torch::Tensor q, torch::Tensor k, torch::Tensor v, torch::Tensor cos, torch::Tensor sin, double scale, int64_t groups) {
    TORCH_CHECK(q.is_cuda(), "q must be CUDA/HIP tensor");
    TORCH_CHECK(k.is_cuda() && v.is_cuda(), "k/v must be CUDA/HIP tensors");
    TORCH_CHECK(cos.is_cuda() && sin.is_cuda(), "cos/sin must be CUDA/HIP tensors");
    TORCH_CHECK(q.scalar_type() == at::kFloat, "FP32 only");
    TORCH_CHECK(k.scalar_type() == at::kFloat && v.scalar_type() == at::kFloat, "FP32 only");
    TORCH_CHECK(cos.scalar_type() == at::kFloat && sin.scalar_type() == at::kFloat, "FP32 only");
    TORCH_CHECK(q.dim() == 4 && k.dim() == 4 && v.dim() == 4, "q/k/v must be 4D");
    TORCH_CHECK(q.size(3) == 128, "This optimized kernel currently supports head_dim==128");

    const int B = (int)q.size(0);
    const int H = (int)q.size(1);
    const int L = (int)q.size(2);
    const int D = (int)q.size(3);
    const int KVH = (int)k.size(1);

    TORCH_CHECK(k.size(0) == B && v.size(0) == B, "batch mismatch");
    TORCH_CHECK(k.size(2) == L && v.size(2) == L, "seq mismatch");
    TORCH_CHECK(k.size(3) == D && v.size(3) == D, "head_dim mismatch");

    auto out = torch::empty({B, L, H * D}, q.options());

    const int64_t qs0 = q.stride(0);
    const int64_t qs1 = q.stride(1);
    const int64_t qs2 = q.stride(2);

    const int64_t ks0 = k.stride(0);
    const int64_t ks1 = k.stride(1);
    const int64_t ks2 = k.stride(2);

    const int64_t vs0 = v.stride(0);
    const int64_t vs1 = v.stride(1);
    const int64_t vs2 = v.stride(2);

    // cos/sin: [1,1,L,D]
    TORCH_CHECK(cos.dim() == 4 && sin.dim() == 4, "cos/sin must be 4D");
    TORCH_CHECK(cos.size(2) >= L && cos.size(3) == D, "cos shape mismatch");
    TORCH_CHECK(sin.size(2) >= L && sin.size(3) == D, "sin shape mismatch");

    const int64_t cs2 = cos.stride(2);
    const int64_t cs3 = cos.stride(3);
    const int64_t ss2 = sin.stride(2);
    const int64_t ss3 = sin.stride(3);

    const int64_t os0 = out.stride(0);
    const int64_t os1 = out.stride(1);

    const dim3 grid(L, H, B);
    const dim3 block(64);

