def rotate_half(x):
    x1 = x[..., : x.shape[-1] // 2]
    x2 = x[..., x.shape[-1] // 2 :]
    return torch.cat((-x2, x1), dim=-1)


class RotaryEmbedding(nn.Module):
    def __init__(self, dim, max_position_embeddings=4096, base=10000.0):
        super().__init__()
        self.dim = dim
        self.max_position_embeddings = max_position_embeddings
        self.base = base
        inv_freq = 1.0 / (self.base ** (torch.arange(0, self.dim, 2, dtype=torch.float32) / self.dim))
        self.register_buffer("inv_freq", inv_freq, persistent=False)

    @torch.no_grad()
    def forward(self, x, seq_len=None):
        if seq_len is None:
            seq_len = x.shape[-2]
        t = torch.arange(seq_len, device=x.device, dtype=torch.float32)
        freqs = torch.outer(t, self.inv_freq)
        emb = torch.cat((freqs, freqs), dim=-1)
        return emb.cos().unsqueeze(0).unsqueeze(0), emb.sin().unsqueeze(0).unsqueeze(0)


class ModelNew(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        num_attention_heads: int,
        num_key_value_heads: int,
        head_dim: int,
        max_position_embeddings: int = 4096,
        rope_theta: float = 10000.0,
        attention_dropout: float = 0.0,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.num_heads = num_attention_heads
        self.num_kv_heads = num_key_value_heads
        self.head_dim = head_dim
        self.num_key_value_groups = num_attention_heads // num_key_value_heads
        self.attention_dropout = attention_dropout
        self.softmax_scale = head_dim ** (-0.5)

        self.q_proj = nn.Linear(hidden_size, num_attention_heads * head_dim, bias=False)
        self.k_proj = nn.Linear(hidden_size, num_key_value_heads * head_dim, bias=False)
        self.v_proj = nn.Linear(hidden_size, num_key_value_heads * head_dim, bias=False)
        self.o_proj = nn.Linear(num_attention_heads * head_dim, hidden_size, bias=False)

        self.rotary_emb = RotaryEmbedding(
            head_dim,
            max_position_embeddings=max_position_embeddings,
            base=rope_theta,
        )

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        # FP32 kernel: keep computations in FP32
        hidden_states = hidden_states.to(dtype=torch.float32)
        bsz, q_len, _ = hidden_states.size()

        # Projections (left to PyTorch/rocBLAS)
        q = self.q_proj(hidden_states)
        k = self.k_proj(hidden_states)
        v = self.v_proj(hidden_states)

        # Reshape to [B, H, L, D] and [B, KVH, L, D] (strided, no copies)
        q = q.view(bsz, q_len, self.num_heads, self.head_dim).transpose(1, 2)
        k = k.view(bsz, q_len, self.num_kv_heads, self.head_dim).transpose(1, 2)
        v = v.view(bsz, q_len, self.num_kv_heads, self.head_dim).transpose(1, 2)

        # Rotary embedding tables
        cos, sin = self.rotary_emb(v, seq_len=q_len)

        # Fused attention: produces [B, L, H*D]
        if self.head_dim != 128 or q.dtype != torch.float32:
            # Conservative fallback (shouldn't trigger for the provided benchmark)
            # Apply RoPE using PyTorch and run baseline attention without explicit KV repeat.
            # (Still avoids materializing attention weights if possible.)
            q_embed = (q * cos) + (rotate_half(q) * sin)
            k_embed = (k * cos) + (rotate_half(k) * sin)
            # Implicit KV repeat using indexing
            # [B, H, L, D]
            kv_h = torch.arange(self.num_heads, device=q.device) // self.num_key_value_groups
            k_rep = k_embed[:, kv_h]
            v_rep = v[:, kv_h]
            attn = torch.matmul(q_embed, k_rep.transpose(2, 3)) * self.softmax_scale
            causal = torch.triu(torch.ones(q_len, q_len, device=q.device, dtype=torch.bool), diagonal=1)
            attn = attn.masked_fill(causal, float('-inf'))
            attn = F.softmax(attn, dim=-1, dtype=torch.float32)
            out = torch.matmul(attn, v_rep)
            out = out.transpose(1, 2).contiguous().view(bsz, q_len, self.num_heads * self.head_dim)
        else:
            out = _gqa_ext.gqa_flash_attn_rope_fwd(q, k, v, cos, sin, float(self.softmax_scale), int(self.num_key_value_groups))

        # Output projection
        out = self.o_proj(out)
        return out


